## 4. API Barrel Export (`src/lib/api/index.ts`)

**File:** `D:\CLAUDE\Project\zakuppro\zakuppro\src\lib\api\index.ts`

This barrel file re-exports all API modules and their associated types:

```typescript
// Re-export the apiClient and its utility functions
export { apiClient, apiFetch, get, post, put, patch, del, throwErrorOnError, isSuccess, isFailure } from '@/lib/api-client';
export type { ApiResult, RequestOptions } from '@/lib/api-client';

// One re-export block per API module -- both the function object and relevant types
export { projectsApi } from '@/lib/api/projects';
export type { ProjectResponse, ProjectCreate, ProjectUpdate, ... } from '@/types/fastapi';

export { suppliersApi } from '@/lib/api/suppliers';
export type { SupplierResponse, SupplierCreate, SupplierUpdate } from '@/types/fastapi';

export { invoicesApi } from '@/lib/api/invoices';
export type { InvoiceResponse, InvoiceCreate, ... } from '@/types/fastapi';

// ... same for stockItemsApi, analyticsApi ...

// Common types at the bottom
export type { ApiError, PaginatedResponse, ListQueryParams, DateRangeQueryParams, DateTime } from '@/types/fastapi';
```

